$c=json_decode(file_get_contents($argv[1]),true);if(!isset($c['database']))$c=['database'=>$c];$c['database']['name']='wexashelf_preflight_080';$c['site']=['url'=>'http://localhost/preflight'];$db=Database::connect($c);if($db->query('SHOW TABLES')->fetchAll())throw new RuntimeException('Dedicated preflight schema must be empty.');Database::migrate($db);$repo=new Repository($db,$c);$storage=sys_get_temp_dir().'/wexa-preflight-'.bin2hex(random_bytes(6));mkdir($storage,0700);$prior=getenv('WEXA_STORAGE_PATH');putenv('WEXA_STORAGE_PATH='.$storage);
